def find_nth_good_integer(N: int) -> int:
    even_digits = [0, 2, 4, 6, 8]
    N -= 1
    good_integer_digits = []
    while N > 0:
        remainder = N % 5
        good_integer_digits.append(even_digits[remainder])
        N //= 5
    good_integer_digits.reverse()
    if not good_integer_digits:
        good_integer_digits.append(0)
    return int(''.join(map(str, good_integer_digits)))
